 public static final int AUDIO_START = 0x6dcb, AUDIO_END = 0x7fc6;
 public static void tiles(final int set) {
  if (set == 0) { RomMemory.copyToVram(TITLE,0,0x8000,0,4096); }
  else { RomMemory.copyToVram(GAMEPLAY,0,0x8000,0,4096); }
 }
 public static int audioData(final int address) {
  if (address < AUDIO_START || address >= AUDIO_END) { return 0; }
  return AUDIO[address-AUDIO_START] & 255;
 }
 public static int audioWord(final int address) {
  if (address < AUDIO_START || address >= AUDIO_END-1) { return 0; }
  return RomMemory.readIntLE(AUDIO,address-AUDIO_START) & 65535;
 }
